cat > /opt/agentrush-runner/push-images.sh <<'AGENTRUSH_EOF'
#!/usr/bin/env bash
# Push the sandbox, browser and egress images to a Vultr Container Registry and pin the runner to
# their exact digests. Run on the executor VM after `docker login <registry host>`.
# The script logs out again at the end, so the executor keeps holding no secrets.
# Usage: bash /opt/agentrush-runner/push-images.sh atl.vultrcr.com/countersign
set -euo pipefail
REG="${1:?usage: push-images.sh <registry, for example atl.vultrcr.com/countersign>}"
HOST="${REG%%/*}"
TAG="$(date -u +%Y%m%d-%H%M)"
ENVF=/etc/agentrush/runner.env
declare -A VAR=([agentrush-sandbox]=SANDBOX_IMAGE [agentrush-browser]=BROWSER_IMAGE [agentrush-egress]=EGRESS_IMAGE)
for img in agentrush-sandbox agentrush-browser agentrush-egress; do
  echo "==> $img"
  docker tag "$img:latest" "$REG/$img:$TAG"
  docker push -q "$REG/$img:$TAG" >/dev/null
  DIGEST="$(docker image inspect --format '{{range .RepoDigests}}{{println .}}{{end}}' "$REG/$img:$TAG" | grep "^$REG/$img@sha256:" | head -1)"
  if [ -z "$DIGEST" ]; then echo "ERROR: no digest for $img" >&2; exit 1; fi
  if grep -q "^${VAR[$img]}=" "$ENVF"; then
    sed -i "s#^${VAR[$img]}=.*#${VAR[$img]}=$DIGEST#" "$ENVF"
  else
    echo "${VAR[$img]}=$DIGEST" >> "$ENVF"
  fi
  echo "    pinned $DIGEST"
done
docker logout "$HOST" >/dev/null 2>&1 || true
rm -f /root/.docker/config.json
systemctl restart agentrush-runner
sleep 3
echo
echo "Runner now uses images pinned by digest. Registry credentials removed from this VM."
grep -E '^(SANDBOX|BROWSER|EGRESS)_IMAGE=' "$ENVF"
AGENTRUSH_EOF

cat > /opt/agentrush-runner/update-runner.sh <<'AGENTRUSH_EOF'
#!/usr/bin/env bash
# Update only the runner program on the executor VM. Keeps the runner token, the private-IP bind
# and the image digests pinned by push-images.sh. Run as root:
#   curl -fsSL https://raw.githubusercontent.com/Aashir01/receipts-agents/main/runner/update-runner.sh | bash
set -euo pipefail
SRC="${1:-https://raw.githubusercontent.com/Aashir01/receipts-agents/main}"
DIR=/opt/agentrush-runner
echo "==> Downloading the latest runner"
curl -fsSL "$SRC/runner/app.py" -o "$DIR/app.py.new"
python3 -c "import ast,sys; ast.parse(open(sys.argv[1]).read())" "$DIR/app.py.new"
cp "$DIR/app.py" "$DIR/app.py.bak" 2>/dev/null || true
mv "$DIR/app.py.new" "$DIR/app.py"
echo "==> Installing the signing library"
"$DIR/venv/bin/pip" install -q cryptography
echo "==> Restarting the runner"
systemctl restart agentrush-runner
sleep 3
BIND=$(grep '^RUNNER_BIND=' /etc/agentrush/runner.env | cut -d= -f2-)
curl -fsS "http://${BIND:-127.0.0.1}:8080/health" | python3 -c '
import json, sys
d = json.load(sys.stdin)
print("runner ok:", d.get("ok"), "| signs results:", d.get("signing"))
for k, v in (d.get("images") or {}).items():
    print(f"  {k}: {v.get(\"digest\", \"?\")[:90]}")'
echo "Done. Previous version kept at $DIR/app.py.bak"
AGENTRUSH_EOF

echo "==> Creating Python environment"
python3 -m venv /opt/agentrush-runner/venv
/opt/agentrush-runner/venv/bin/pip install -q --upgrade pip
/opt/agentrush-runner/venv/bin/pip install -q fastapi "uvicorn[standard]" pydantic cryptography

echo "==> Building sandbox image (pandas, matplotlib, ...)"
docker build -q -t agentrush-sandbox:latest -f /opt/agentrush-runner/sandbox.Dockerfile /opt/agentrush-runner >/dev/null
echo "==> Building egress proxy image"
docker build -q -t agentrush-egress:latest /opt/agentrush-runner/egress >/dev/null
echo "==> Building browser image (Chromium + Playwright) - takes 3-6 minutes the first time"
docker build -q -t agentrush-browser:latest /opt/agentrush-runner/browser >/dev/null

echo "==> Detecting private (VPC) IP"
PRIV_IP=$(ip -4 -o addr show | awk '$2 !~ /^(docker|br-|lo|veth)/ {print $4}' | cut -d/ -f1 | grep -E '^10\.' | head -1 || true)
if [ -z "$PRIV_IP" ]; then
  echo "ERROR: no 10.x private IP found. Is VPC attached?" >&2
  exit 1
fi

if [ -f /etc/agentrush/runner.env ] && grep -q '^RUNNER_TOKEN=' /etc/agentrush/runner.env; then
  TOKEN=$(grep '^RUNNER_TOKEN=' /etc/agentrush/runner.env | cut -d= -f2-)
else
  TOKEN=$(openssl rand -hex 32)
fi

cat > /etc/agentrush/runner.env <<AGENTRUSH_EOF
RUNNER_TOKEN=$TOKEN
RUNNER_BIND=$PRIV_IP
SANDBOX_IMAGE=agentrush-sandbox:latest
BROWSER_IMAGE=agentrush-browser:latest
EGRESS_IMAGE=agentrush-egress:latest
DOCKER_RUNTIME=runsc
JOBS_DIR=/var/lib/agentrush/jobs
MAX_CONCURRENT=2
AGENTRUSH_EOF
chmod 600 /etc/agentrush/runner.env

echo "==> Starting service"
systemctl daemon-reload
systemctl enable -q agentrush-runner
systemctl restart agentrush-runner
sleep 3

echo "==> Health check"
curl -s "http://$PRIV_IP:8080/health" && echo

echo
echo "=================================================================="
echo " Runner is listening ONLY on the private network: http://$PRIV_IP:8080"
echo " RUNNER_TOKEN (copy into your notes; never commit it):"
echo "   $TOKEN"
echo "=================================================================="
